Q: Calculate duration by start and end hour A: <ol>
<li>Convert the HH:MM:SS to seconds.</li>
<li>Subtract the two values - you get the seconds of duration.</li>
<li>Convert the seconds to HH:MM:SS.</li>
</ol>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>/* helper functions */
const format = n =&gt;
  String(n).padStart(2, 0);

const time2seconds = time =&gt; {
  const [hours, minutes, seconds] = time.split(":").map(Number);

  return seconds + minutes * 60 + hours * 60 * 60;
}

const seconds2time = seconds =&gt; {
  const hours = format(Math.floor(seconds / (60 * 60)));
  const minutes = format(Math.floor(seconds / 60) % 60);
  seconds = format(seconds % 60);

  return `${hours}:${minutes}:${seconds}`;
}
/* /helper functions */


const toDuration = ({startTime, endTime}) =&gt;
  seconds2time(time2seconds(endTime) - time2seconds(startTime));


test({
    endTime: "14:00:00",
    startTime: "12:00:00"
})

test({
    endTime: "15:30:00",
    startTime: "11:00:00"
})

test({
    endTime: "18:24:05",
    startTime: "11:47:12"
})

function test(obj) {
  const result = toDuration(obj);

  console.log(`duration between ${obj.startTime} and ${obj.endTime} is: ${result}`);
}</code></pre>
</div>
</div>
</p>

